def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    sep = next((r for r, row in enumerate(grid) if all(v == 2 for v in row)), None)
    if sep is None:
        return out

    bg = max((v for v in set(v for row in grid for v in row) if v != 2),
             key=lambda v: sum(row.count(v) for row in grid))
    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] not in (bg, 2)]
    if not pts:
        return out

    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    patch = [grid[r][c0:c1 + 1] for r in range(r0, r1 + 1)]

    # Move the object to the side of the separator where it already lies,
    # snug against the separator.
    if r1 < sep:
        nr0 = sep - (r1 - r0) - 1
        line = nr0 - 1
    else:
        nr0 = sep + 1
        line = nr0 + (r1 - r0) + 1

    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            out[r][c] = bg

    if 0 <= nr0 and nr0 + len(patch) <= h:
        for dr, row in enumerate(patch):
            out[nr0 + dr][c0:c1 + 1] = row
    if 0 <= line < h:
        out[line] = [8] * w
    return out
